"""The replicated key-value store you will test. Given: you do not edit this file.

Three nodes (0, 1, 2) each hold a copy of every register. Any node can serve a client; that node
becomes the COORDINATOR for the request. The protocol is a multi-writer form of the register
protocol of Attiya, Bar-Noy and Dolev (1995), "ABD". A value is stored with a timestamp, and the higher
timestamp wins.

    write(key, v)   1. ask every node for its (timestamp, value) for the key; wait for 2 of 3 replies
                    2. choose a timestamp higher than every one seen; tell every node to store
                       (timestamp, v); wait for 2 of 3 acknowledgements; reply to the client.
    read(key)       1. ask every node; wait for 2 of 3 replies; take the one with the highest timestamp
                    2. write that (timestamp, value) back to every node; wait for 2 of 3 acks;
                       reply to the client with the value.

Any two groups of 2 out of 3 nodes share at least one node, so a read always meets a node that
holds the latest completed write. Each node keeps its registers in memory (`self.store`) and also
saves them to its disk (`sim.write_disk`) so they survive a crash and restart. The coordinator
retries a request's current phase every 12 ticks, up to 8 times, for the nodes that have not replied.

Messages are tuples whose first item names the handler:  client_write, client_read, client_ok,
query, query_reply, store, store_ack.  `sim` is the simulator from your starter.py.
"""

ZERO = (0, 0, 0)                 # the timestamp of "nothing written yet"
PEERS = (0, 1, 2)
MAJORITY = 2
RETRY_EVERY = 12
MAX_TRIES = 8


class KVNode:
    def __init__(self, node_id, sim, durable):
        self.id = node_id
        self.sim = sim
        self.store = dict(durable.get("store", {}))   # key -> (timestamp, value); timestamp = (counter, node id, request id)
        self.ops = {}                                  # requests this node is coordinating (memory only)

    def on_start(self):
        pass

    def on_message(self, src, msg):
        getattr(self, "on_" + msg[0])(src, *msg[1:])

    # ---------------------------------------------------------------- coordinator side

    def on_client_write(self, client, rid, key, value):
        self._begin(client, rid, "write", key, value)

    def on_client_read(self, client, rid, key):
        self._begin(client, rid, "read", key, None)

    def _begin(self, client, rid, kind, key, value):
        if rid in self.ops:
            return
        self.ops[rid] = {"client": client, "kind": kind, "key": key, "value": value,
                         "phase": "query", "replies": {}, "tries": 0}
        self._send_phase(rid)
        self.sim.set_timer(self.id, RETRY_EVERY, ("retry", rid))

    def _send_phase(self, rid):
        op = self.ops[rid]
        for peer in PEERS:
            if peer in op["replies"]:
                continue
            if op["phase"] == "query":
                self.sim.send(self.id, peer, ("query", rid, op["key"]))
            else:
                self.sim.send(self.id, peer, ("store", rid, op["key"], op["ts"], op["chosen"]))

    def on_timer(self, tag):
        if tag[0] != "retry":
            return
        rid = tag[1]
        op = self.ops.get(rid)
        if op is None:
            return
        op["tries"] += 1
        if op["tries"] > MAX_TRIES:
            del self.ops[rid]                          # give up; the client will time out
            return
        self._send_phase(rid)
        self.sim.set_timer(self.id, RETRY_EVERY, ("retry", rid))

    def on_query_reply(self, src, rid, ts, value):
        op = self.ops.get(rid)
        if op is None or op["phase"] != "query":
            return
        op["replies"][src] = (ts, value)
        if len(op["replies"]) < MAJORITY:
            return
        best_ts, best_value = max(op["replies"].values(), key=lambda r: r[0])
        if op["kind"] == "write":
            op["ts"] = (best_ts[0] + 1, self.id, rid)
            op["chosen"] = op["value"]
        else:
            op["ts"], op["chosen"] = best_ts, best_value   # a read writes back what it is about to return
        op["phase"] = "store"
        op["replies"] = {}
        self._send_phase(rid)

    def on_store_ack(self, src, rid):
        op = self.ops.get(rid)
        if op is None or op["phase"] != "store":
            return
        op["replies"][src] = True
        if len(op["replies"]) >= MAJORITY:
            del self.ops[rid]
            result = op["chosen"] if op["kind"] == "read" else None
            self.sim.send(self.id, op["client"], ("client_ok", rid, result))

    # ---------------------------------------------------------------- replica side

    def on_query(self, src, rid, key):
        ts, value = self.store.get(key, (ZERO, None))
        self.sim.send(self.id, src, ("query_reply", rid, ts, value))

    def on_store(self, src, rid, key, ts, value):
        if ts > self.store.get(key, (ZERO, None))[0]:
            self.store[key] = (ts, value)
        self.sim.write_disk(self.id, "store", dict(self.store))    # save to disk (lands a few ticks later)
        self._ack(src, rid, key, ts)

    def _ack(self, src, rid, key, ts):
        # test instrumentation: remember what this node has promised, for invariant checks
        acked = self.sim.ghost.setdefault("acked", {})
        if ts > acked.get((self.id, key), ZERO):
            acked[(self.id, key)] = ts
        self.sim.send(self.id, src, ("store_ack", rid))
